with prev_events as (select *, lag(reading_ts) over (partition by device_code order by reading_ts, id) as prev_reading_ts from device_readings), gaps as (select *, case when prev_reading_ts is null or reading_ts > prev_reading_ts + interval 20 minutes then 1 else 0 end as is_new_session from prev_events), sessions_device_readings as (select *, sum(is_new_session) over (partition by device_code order by reading_ts, id rows between unbounded preceding and current row) as session_id from gaps) select date_trunc('year', prev_reading_ts) as year_start, case when status_bits >= 12 then 'LARGE' else 'SMALL' end as status_bits_tier, date_trunc('hour', reading_ts) as hour_window, sort_array(collect_set(device_code)) as device_code_list, count(*) filter (where device_code = 'DV-02') as dv_02_rows, min(prev_reading_ts) as first_prev_reading_ts, max(is_new_session) filter (where device_code = 'DV-04') as dv_04_max_is_new_session, count_if(device_code = 'DV-04') as dv_04_events from sessions_device_readings group by date_trunc('year', prev_reading_ts), case when status_bits >= 12 then 'LARGE' else 'SMALL' end, date_trunc('hour', reading_ts)
